import json
def transform(g):
    H=len(g); W=len(g[0])
    # separator cols = all-zero columns
    zc=[c for c in range(W) if all(g[r][c]==0 for r in range(H))]
    # block col ranges between separators
    edges=[-1]+zc+[W]
    ranges=[(edges[i]+1,edges[i+1]) for i in range(len(edges)-1) if edges[i]+1<edges[i+1]]
    bw=ranges[0][1]-ranges[0][0]
    def key(cs):
        return sum(1 for r in range(H) for c in range(cs,cs+bw) if g[r][c]==0)
    order=sorted(range(len(ranges)), key=lambda i:-key(ranges[i][0]))
    out=[row[:] for row in g]
    for k,src in enumerate(order):
        for r in range(H):
            for j in range(bw):
                out[r][ranges[k][0]+j]=g[r][ranges[src][0]+j]
    return out
